package com.pams.module.agent.service;

import org.jsoup.Jsoup;
import org.jsoup.parser.Parser;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

/** Checks rendered page geometry for documents generated by the application. */
@Component
public class WordPageReview {
    public record Issue(int page, String code) {}
    public record Report(String status, int pages, List<Issue> issues, boolean adjusted) {
        public Map<String,Object> facts() {
            return Map.of("status", status, "pages", pages, "issues",
                    issues.stream().map(issue -> Map.of("page", issue.page(), "code", issue.code())).toList(), "adjusted", adjusted);
        }
    }

    private final String office;
    private final String pdfText;
    private final Semaphore slots = new Semaphore(1);

    public WordPageReview(@Value("${pams.agent.word-renderer:}") String office,
                          @Value("${pams.agent.word-pdf-text:}") String pdfText) {
        this.office = office;
        this.pdfText = pdfText;
    }

    Report inspect(byte[] docx) {
        if (office.isBlank() || pdfText.isBlank()) return new Report("NOT_CONFIGURED", 0, List.of(), false);
        if (!slots.tryAcquire()) return new Report("BUSY", 0, List.of(), false);
        Path directory = null;
        try {
            directory = Files.createTempDirectory("pams-word-check-");
            Path input = Files.write(directory.resolve("draft.docx"), docx);
            run(directory, List.of(office, "-env:UserInstallation=" + directory.resolve("profile").toUri(),
                    "--headless", "--convert-to", "pdf", "--outdir", directory.toString(), input.toString()));
            Path pdf = directory.resolve("draft.pdf");
            if (Files.size(pdf) > 16 * 1024 * 1024) return new Report("LIMIT_EXCEEDED", 0, List.of(), false);
            Path geometry = directory.resolve("pages.html");
            run(directory, List.of(pdfText, "-enc", "UTF-8", "-bbox", pdf.toString(), geometry.toString()));
            if (Files.size(geometry) > 4 * 1024 * 1024) return new Report("LIMIT_EXCEEDED", 0, List.of(), false);
            return parse(Files.readString(geometry, StandardCharsets.UTF_8));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new java.util.concurrent.CancellationException("Word 检查已中止");
        } catch (IOException | IllegalArgumentException e) {
            return new Report("RENDER_FAILED", 0, List.of(), false);
        } finally {
            if (directory != null) cleanup(directory);
            slots.release();
        }
    }

    Report inspectRevision(byte[] docx) {
        if (office.isBlank() || pdfText.isBlank()) return new Report("NOT_CONFIGURED", 0, List.of(), false);
        if (!ImportedWordRenderSafety.canRender(docx)) return new Report("UNSUPPORTED_PACKAGE", 0, List.of(), false);
        return inspect(docx);
    }

    static Report parse(String markup) throws IOException {
        var pages = Jsoup.parse(markup, "", Parser.xmlParser()).select("page");
        if (pages.isEmpty()) throw new IOException("渲染器未返回页信息");
        var issues = new ArrayList<Issue>();
        for (int index = 0; index < pages.size(); index++) {
            var page = pages.get(index);
            int number = index + 1;
            var words = page.select("word");
            if (words.isEmpty()) issues.add(new Issue(number, "EMPTY_PAGE"));
            double width = Double.parseDouble(page.attr("width"));
            double height = Double.parseDouble(page.attr("height"));
            if (!Double.isFinite(width) || !Double.isFinite(height) || width <= 0 || height <= 0) {
                throw new IOException("无效的页尺寸");
            }
            boolean clipped = false;
            boolean unreadable = false;
            for (var word : words) {
                double xMin = Double.parseDouble(word.attr("xMin"));
                double yMin = Double.parseDouble(word.attr("yMin"));
                double xMax = Double.parseDouble(word.attr("xMax"));
                double yMax = Double.parseDouble(word.attr("yMax"));
                if (!Double.isFinite(xMin + yMin + xMax + yMax)) throw new IOException("无效的文字位置");
                clipped |= xMin < -1 || yMin < -1 || xMax > width + 1 || yMax > height + 1;
                unreadable |= word.text().contains("\uFFFD");
            }
            if (clipped) issues.add(new Issue(number, "TEXT_OUTSIDE_PAGE"));
            if (unreadable) issues.add(new Issue(number, "UNREADABLE_TEXT"));
        }
        return new Report(issues.isEmpty() ? "PASSED" : "ISSUES", pages.size(), List.copyOf(issues), false);
    }

    private static void run(Path directory, List<String> command) throws IOException, InterruptedException {
        var process = new ProcessBuilder(command).directory(directory.toFile())
                .redirectOutput(ProcessBuilder.Redirect.DISCARD)
                .redirectError(ProcessBuilder.Redirect.DISCARD).start();
        try {
            if (!process.waitFor(20, TimeUnit.SECONDS) || process.exitValue() != 0) throw new IOException("Word 页面检查失败");
        } finally {
            if (process.isAlive()) {
                process.descendants().forEach(ProcessHandle::destroyForcibly);
                process.destroyForcibly();
            }
        }
    }

    private static void cleanup(Path directory) {
        try (var paths = Files.walk(directory)) {
            for (Path path : paths.sorted(Comparator.reverseOrder()).toList()) Files.deleteIfExists(path);
        } catch (IOException ignored) { /* Temporary directory cleanup can be retried by the host. */ }
    }
}
